import { Download, Printer, Ticket } from 'lucide-react';
import { api } from '../lib/api.js';
import { fmtDate, fmtTime, fmtDateTime } from '../lib/format.js';
import { useToast } from '../context/ToastContext.jsx';

/** On-screen version of the registration card. The PDF is generated by the server. */
export default function RegistrationCard({ booking: b, highlight }) {
  const toast = useToast();
  const download = async () => {
    try { await api.file(`/bookings/${b.booking_id}/card`, { filename: `registration-card-${b.booking_ref}.pdf` }); toast.ok('Registration card downloaded.'); }
    catch (e) { toast.error(e.message); }
  };
  const print = async () => {
    try { await api.file(`/bookings/${b.booking_id}/card`, { open: true }); }
    catch (e) { toast.error(e.message); }
  };
  return (
    <article className={`reg-card ${highlight ? 'highlight' : ''}`} aria-label={`Registration card for ${b.title}`}>
      <header><strong><Ticket size={18} style={{ verticalAlign: '-3px' }} aria-hidden /> CampusSeat registration card</strong><span className="small">Proof of attendance</span></header>
      <dl className="content">
        <div className="wide"><dt>Event</dt><dd style={{ fontSize: '1.2rem' }}>{b.title}</dd></div>
        <div><dt>Name</dt><dd>{b.full_name}</dd></div>
        <div><dt>Student/staff number</dt><dd>{b.student_number}</dd></div>
        <div><dt>Date</dt><dd>{fmtDate(b.event_date)}</dd></div>
        <div><dt>Time</dt><dd>{fmtTime(b.start_time)} to {fmtTime(b.end_time)}</dd></div>
        <div className="wide"><dt>Venue</dt><dd>{b.venue}</dd></div>
      </dl>
      <div className="cut" aria-hidden />
      <dl className="content">
        <div><dt>Booking reference</dt><dd className="ref">{b.booking_ref}</dd></div>
        <div><dt>Booked</dt><dd>{fmtDateTime(b.booked_at)}</dd></div>
      </dl>
      <footer className="row no-print">
        <button className="btn" onClick={download}><Download size={18} aria-hidden />Download PDF</button>
        <button className="btn secondary" onClick={print}><Printer size={18} aria-hidden />Print</button>
      </footer>
    </article>
  );
}
